// Original SAT English (Reading & Writing) practice questions, written
// for ScholarCompass — not reproduced from any real SAT test. Category
// names match the four official digital SAT R&W domains (generic,
// widely-used educational category labels, not test content itself).
// 20 questions per category, 80 total.

export const SAT_CATEGORIES = [
  { id: "craft-and-structure", label: "Craft and Structure" },
  { id: "information-and-ideas", label: "Information and Ideas" },
  { id: "standard-english-conventions", label: "Standard English Conventions" },
  { id: "expression-of-ideas", label: "Expression of Ideas" },
];

export const SAT_QUESTIONS = {
  "craft-and-structure": [
  { id: "CS01", passage: "Early microscopes could magnify objects only a few hundred times, so the smallest bacteria remained entirely ______ to seventeenth-century scientists.", prompt: "Which choice completes the text with the most logical and precise word?", options: [{ id: "A", text: "visible" }, { id: "B", text: "invisible" }, { id: "C", text: "familiar" }, { id: "D", text: "irrelevant" }], answer: "B", explanation: "The sentence sets up a contrast: limited magnification meant scientists could NOT see the smallest bacteria, so 'invisible' fits." },
  { id: "CS02", passage: "The novelist's prose is often praised as spare, yet a closer reading reveals sentences dense with unexpected, almost ______ detail.", prompt: "Which choice completes the text with the most logical and precise word?", options: [{ id: "A", text: "predictable" }, { id: "B", text: "superfluous" }, { id: "C", text: "ornate" }, { id: "D", text: "muted" }], answer: "C", explanation: "'Yet' signals a contrast with 'spare,' so a word meaning heavily decorated or elaborate ('ornate') fits best." },
  { id: "CS03", passage: "Because the committee's report relied on outdated census figures, its conclusions about population growth were quickly deemed ______ by demographers.", prompt: "Which choice completes the text with the most logical and precise word?", options: [{ id: "A", text: "authoritative" }, { id: "B", text: "unreliable" }, { id: "C", text: "comprehensive" }, { id: "D", text: "celebrated" }], answer: "B", explanation: "Outdated data would undermine the report's credibility, making 'unreliable' the logical fit." },
  { id: "CS04", passage: "In this passage, the author describes a rural bridge in painstaking technical detail, listing its exact dimensions, materials, and construction date.", prompt: "Which choice best describes the main purpose of this description?", options: [{ id: "A", text: "To argue that the bridge should be demolished" }, { id: "B", text: "To establish the bridge as a precise, verifiable historical object rather than a vague memory" }, { id: "C", text: "To criticize the engineers who built the bridge" }, { id: "D", text: "To compare the bridge unfavorably to a more famous structure" }], answer: "B", explanation: "Precise technical detail (dimensions, materials, date) grounds the bridge as a documented fact, not a hazy recollection — matching option B." },
  { id: "CS05", passage: "A marine biologist's field notes open with a description of choppy water and poor visibility before pivoting to a detailed account of a rare squid sighting.", prompt: "Which choice best states the function of the opening description of the water conditions?", options: [{ id: "A", text: "It establishes the difficulty of the observation, making the later sighting seem more remarkable" }, { id: "B", text: "It proves the squid sighting was inaccurate" }, { id: "C", text: "It is unrelated to the rest of the notes" }, { id: "D", text: "It criticizes the equipment used" }], answer: "A", explanation: "Noting poor conditions before a notable sighting heightens the significance of that sighting — option A." },
  { id: "CS06", passage: "Text 1: A historian argues that a nation's founding myths reveal more about its present anxieties than its actual past.\nText 2: A second historian counters that founding myths, however exaggerated, still preserve genuine details about early events.", prompt: "Based on the texts, how would the historian in Text 2 most likely respond to the claim in Text 1?", options: [{ id: "A", text: "By agreeing entirely that founding myths reveal nothing about the past" }, { id: "B", text: "By arguing that founding myths, despite distortion, retain some historical value" }, { id: "C", text: "By dismissing the study of founding myths altogether" }, { id: "D", text: "By claiming founding myths are perfectly accurate" }], answer: "B", explanation: "Text 2's historian believes myths preserve 'genuine details,' a partial pushback rather than total agreement or total accuracy — option B." },
  { id: "CS07", passage: "Despite the CEO's confident public statements, internal memos revealed a company deeply ______ about its chances of meeting quarterly targets.", prompt: "Which choice completes the text with the most logical and precise word?", options: [{ id: "A", text: "optimistic" }, { id: "B", text: "apprehensive" }, { id: "C", text: "indifferent" }, { id: "D", text: "boastful" }], answer: "B", explanation: "'Despite ... confident statements' signals a contrast — the memos show worry, i.e., 'apprehensive.'" },
  { id: "CS08", passage: "The poet's early work is dismissed by some critics as merely ______, imitating older styles without adding anything original.", prompt: "Which choice completes the text with the most logical and precise word?", options: [{ id: "A", text: "derivative" }, { id: "B", text: "innovative" }, { id: "C", text: "obscure" }, { id: "D", text: "polished" }], answer: "A", explanation: "'Imitating older styles without adding anything original' is the definition of 'derivative.'" },
  { id: "CS09", passage: "A travel writer opens an essay about a crowded market by focusing narrowly on a single vendor's hands as they fold dumplings.", prompt: "Which choice best describes the effect of this narrow opening focus?", options: [{ id: "A", text: "It confuses the reader about the setting" }, { id: "B", text: "It creates an intimate entry point before the essay expands to the wider scene" }, { id: "C", text: "It suggests the vendor is unimportant" }, { id: "D", text: "It argues against visiting crowded markets" }], answer: "B", explanation: "Starting on a small, human detail before widening the lens is a classic technique for drawing readers into a larger scene — option B." },
  { id: "CS10", passage: "The scientist's explanation, though technically accurate, was so ______ that most of the audience lost track of her argument halfway through.", prompt: "Which choice completes the text with the most logical and precise word?", options: [{ id: "A", text: "concise" }, { id: "B", text: "convoluted" }, { id: "C", text: "engaging" }, { id: "D", text: "simple" }], answer: "B", explanation: "Losing track of the argument implies the explanation was overly complicated — 'convoluted.'" },
  { id: "CS11", passage: "Text 1: An economist claims that automation will eliminate more jobs than it creates over the next decade.\nText 2: A second economist points to past technological shifts, noting that new job categories have historically offset losses.", prompt: "The economist in Text 2 would most likely view the claim in Text 1 as:", options: [{ id: "A", text: "certainly correct" }, { id: "B", text: "overly pessimistic given historical patterns" }, { id: "C", text: "irrelevant to economics" }, { id: "D", text: "understated" }], answer: "B", explanation: "Text 2 emphasizes that new jobs have historically offset losses, suggesting skepticism toward Text 1's pessimistic prediction — option B." },
  { id: "CS12", passage: "A memoirist describes her grandmother's kitchen using short, fragmented sentences that mimic the scattered nature of memory itself.", prompt: "Which choice best explains the purpose of the sentence structure described?", options: [{ id: "A", text: "To confuse the reader intentionally" }, { id: "B", text: "To formally mirror the fragmented, non-linear way memories are recalled" }, { id: "C", text: "To follow strict grammatical convention" }, { id: "D", text: "To shorten the essay's overall length" }], answer: "B", explanation: "Matching sentence form to the fragmented nature of memory is a deliberate stylistic choice — option B." },
  { id: "CS13", passage: "Although the drug showed promise in early trials, researchers remained ______, insisting that years of further testing were needed before any conclusions could be drawn.", prompt: "Which choice completes the text with the most logical and precise word?", options: [{ id: "A", text: "cautious" }, { id: "B", text: "triumphant" }, { id: "C", text: "careless" }, { id: "D", text: "certain" }], answer: "A", explanation: "Insisting on further testing before conclusions signals caution, not certainty or triumph." },
  { id: "CS14", passage: "A columnist opens an article on climate policy with a personal anecdote about a flooded childhood home before shifting to statistics on rising sea levels.", prompt: "Which choice best describes the function of the opening anecdote?", options: [{ id: "A", text: "To provide a purely statistical argument" }, { id: "B", text: "To ground an abstract, data-heavy topic in a concrete, personal experience" }, { id: "C", text: "To criticize the reader" }, { id: "D", text: "To replace the need for evidence entirely" }], answer: "B", explanation: "Personal anecdotes commonly serve to humanize abstract data-driven topics before the argument turns to statistics — option B." },
  { id: "CS15", passage: "The negotiator's reputation for being ______ made even hostile counterparts willing to sit down at the table, confident that any agreement would be scrupulously honored.", prompt: "Which choice completes the text with the most logical and precise word?", options: [{ id: "A", text: "unreliable" }, { id: "B", text: "trustworthy" }, { id: "C", text: "aggressive" }, { id: "D", text: "indecisive" }], answer: "B", explanation: "Counterparts trusting agreements would be 'scrupulously honored' implies a reputation for being 'trustworthy.'" },
  { id: "CS16", passage: "Text 1: A sociologist argues that social media has fundamentally weakened face-to-face community bonds.\nText 2: A second sociologist contends that online platforms have simply created new, different forms of community rather than destroying old ones.", prompt: "How does the sociologist in Text 2 most directly challenge the claim in Text 1?", options: [{ id: "A", text: "By denying that social media has any effect on community" }, { id: "B", text: "By reframing the change as a transformation rather than a decline" }, { id: "C", text: "By agreeing that community bonds are weaker" }, { id: "D", text: "By focusing entirely on economic effects" }], answer: "B", explanation: "Text 2 reframes the same phenomenon (change caused by social media) as transformation, not decline — option B directly challenges Text 1's framing." },
  { id: "CS17", passage: "The architect's design was criticized as ______, prioritizing visual drama over the practical needs of the people who would actually use the building.", prompt: "Which choice completes the text with the most logical and precise word?", options: [{ id: "A", text: "functional" }, { id: "B", text: "ostentatious" }, { id: "C", text: "economical" }, { id: "D", text: "modest" }], answer: "B", explanation: "Prioritizing visual drama over practicality suggests a showy, excessive design — 'ostentatious.'" },
  { id: "CS18", passage: "A biographer structures a chapter around a single object, a pocket watch, returning to it repeatedly as a way of tracing the subject's shifting fortunes.", prompt: "Which choice best describes this organizational strategy?", options: [{ id: "A", text: "Using a chronological list of unrelated events" }, { id: "B", text: "Using a recurring concrete object as a unifying thread across the narrative" }, { id: "C", text: "Avoiding any structure at all" }, { id: "D", text: "Relying solely on dialogue" }], answer: "B", explanation: "Returning repeatedly to one object as an organizing device is a recognizable structural technique — option B." },
  { id: "CS19", passage: "Once celebrated as visionary, the urban planner's proposals are now regarded by many as ______, having failed to anticipate how quickly the city's population would grow.", prompt: "Which choice completes the text with the most logical and precise word?", options: [{ id: "A", text: "prophetic" }, { id: "B", text: "shortsighted" }, { id: "C", text: "meticulous" }, { id: "D", text: "progressive" }], answer: "B", explanation: "Failing to anticipate rapid growth is the definition of 'shortsighted,' contrasting with the earlier praise as 'visionary.'" },
  { id: "CS20", passage: "Text 1: A literary critic argues that a novel's ambiguous ending reflects the author's deliberate refusal to offer easy moral resolution.\nText 2: A second critic argues the same ending is simply an unfinished draft that the author never revised.", prompt: "The two texts differ mainly in their view of:", options: [{ id: "A", text: "the novel's setting" }, { id: "B", text: "whether the ambiguous ending was an intentional artistic choice or an accident" }, { id: "C", text: "the novel's genre" }, { id: "D", text: "the author's biography" }], answer: "B", explanation: "Text 1 sees deliberate artistic intent; Text 2 sees an accident of an unfinished draft — the central disagreement is intentionality, option B." }
  ],
  "information-and-ideas": [
  { id: "II01", passage: "A recent study tracked 500 households over ten years and found that families who ate dinner together at least five nights a week reported higher rates of adolescent academic achievement, though the study's authors noted they could not rule out that both behaviors stem from a third factor, such as parental availability.", prompt: "Which choice best states the main finding of the study described?", options: [{ id: "A", text: "Eating dinner together causes higher academic achievement" }, { id: "B", text: "A correlation exists between family dinners and academic achievement, but causation is uncertain" }, { id: "C", text: "Parental availability has no effect on academic achievement" }, { id: "D", text: "The study followed households for twenty years" }], answer: "B", explanation: "The passage reports a correlation while explicitly noting the authors couldn't rule out a confounding factor — option B captures this nuance." },
  { id: "II02", passage: "Coral polyps expel the algae living in their tissues when water temperatures rise even slightly above normal, a process that drains the coral of its color and, if prolonged, its main source of nutrients.", prompt: "According to the text, what happens to coral when water temperatures rise?", options: [{ id: "A", text: "The coral grows more algae" }, { id: "B", text: "The coral expels algae, losing color and eventually nutrients" }, { id: "C", text: "The coral becomes more colorful" }, { id: "D", text: "The water temperature has no effect on coral" }], answer: "B", explanation: "The text directly states rising temperature causes coral to expel algae, draining color and eventually nutrients — option B." },
  { id: "II03", passage: "Although bats are often associated with caves, many species roost instead in tree foliage, rock crevices, or even human structures such as barns and bridges, adapting their roosting habits to whatever shelter is locally available.", prompt: "Which choice best describes the main idea of the text?", options: [{ id: "A", text: "Bats only roost in caves" }, { id: "B", text: "Bats are flexible in choosing roosting locations based on availability" }, { id: "C", text: "Bats cannot survive without caves" }, { id: "D", text: "Bats prefer bridges over all other shelters" }], answer: "B", explanation: "The passage emphasizes adaptability across multiple roost types — option B is the main idea." },
  { id: "II04", passage: "A city's public transit ridership fell by 12 percent after fare prices increased, but ridership on the city's free shuttle routes rose by 30 percent over the same period, suggesting that some riders shifted to free alternatives rather than abandoning public transit altogether.", prompt: "Which inference is most strongly supported by the text?", options: [{ id: "A", text: "Fewer people are using any form of public transit" }, { id: "B", text: "Some riders likely switched from paid to free transit options rather than stopping transit use entirely" }, { id: "C", text: "Fare increases had no effect on ridership" }, { id: "D", text: "The free shuttle routes were canceled" }], answer: "B", explanation: "The rise in free-shuttle ridership alongside the fall in paid ridership supports a shift between options, not abandonment — option B." },
  { id: "II05", passage: "A researcher comparing two decades of rainfall data found no significant long-term trend in total annual rainfall for the region, but did find that rainfall increasingly arrived in fewer, more intense storms rather than spread evenly across the year.", prompt: "Which choice best captures the finding described?", options: [{ id: "A", text: "Total rainfall has increased dramatically" }, { id: "B", text: "Total rainfall is roughly stable, but its distribution has become more concentrated in intense events" }, { id: "C", text: "Rainfall has become perfectly evenly distributed" }, { id: "D", text: "The region has entered a drought" }], answer: "B", explanation: "The passage distinguishes total amount (stable) from distribution (more concentrated) — option B reflects both parts accurately." },
  { id: "II06", passage: "In a survey of 1,200 small business owners, 68 percent reported that access to affordable credit was their single greatest obstacle to expansion, ahead of concerns about labor costs or regulatory compliance.", prompt: "Which choice is best supported by the data in the text?", options: [{ id: "A", text: "Labor costs were the top concern for most owners" }, { id: "B", text: "Affordable credit access was the most commonly cited obstacle to expansion" }, { id: "C", text: "Regulatory compliance was not mentioned at all" }, { id: "D", text: "All 1,200 owners agreed on every issue" }], answer: "B", explanation: "68% citing credit access as the greatest obstacle, ahead of the other two options, directly supports option B." },
  { id: "II07", passage: "The apprenticeship program placed 340 graduates in manufacturing jobs last year, a figure the program's director called encouraging, while also noting that the program's total funding was cut by 15 percent for the coming year.", prompt: "Which choice best describes the relationship between the two facts presented in the text?", options: [{ id: "A", text: "The funding cut caused the placement figure to rise" }, { id: "B", text: "A positive outcome (placements) is reported alongside a separate concern (reduced funding) about sustaining that outcome" }, { id: "C", text: "The two facts are entirely unrelated to the program" }, { id: "D", text: "The placement figure will definitely increase next year" }], answer: "B", explanation: "The text juxtaposes a good result with a funding concern for the future, without claiming causation — option B." },
  { id: "II08", passage: "Unlike most spiders, which spin new webs from scratch, the species Larinioides cornutus often repairs and reuses portions of its existing web, conserving the energy otherwise spent producing new silk.", prompt: "According to the text, how does Larinioides cornutus differ from most other spiders?", options: [{ id: "A", text: "It never builds webs" }, { id: "B", text: "It reuses parts of existing webs rather than always starting anew" }, { id: "C", text: "It produces more silk than other spiders" }, { id: "D", text: "It cannot repair webs" }], answer: "B", explanation: "The text states this species repairs/reuses web portions instead of spinning entirely new webs — option B." },
  { id: "II09", passage: "A city council report found that while overall crime rates fell by 8 percent citywide last year, crime in the downtown business district rose by 4 percent over the same period.", prompt: "Which choice best describes the finding of the report?", options: [{ id: "A", text: "Crime fell uniformly across every part of the city" }, { id: "B", text: "The citywide trend downward did not hold true for the downtown district, which saw an increase" }, { id: "C", text: "Downtown crime fell faster than the citywide average" }, { id: "D", text: "The report found no change in crime anywhere" }], answer: "B", explanation: "The passage explicitly contrasts the citywide decrease with a downtown increase — option B." },
  { id: "II10", passage: "Paleontologists once assumed that a newly discovered fossil belonged to a juvenile of an already-known species, but closer analysis of bone density and growth rings revealed it was a fully mature individual of a previously unidentified species.", prompt: "Which choice best describes how the scientists' understanding changed?", options: [{ id: "A", text: "They confirmed their original assumption" }, { id: "B", text: "They revised their initial assumption after further analysis revealed a new, distinct species" }, { id: "C", text: "They decided the fossil was too damaged to study" }, { id: "D", text: "They concluded no new species existed" }], answer: "B", explanation: "The passage describes an initial assumption overturned by later evidence — option B." },
  { id: "II11", passage: "A nutrition label review found that products marketed as 'low fat' often contained more added sugar than their standard counterparts, a substitution manufacturers commonly use to preserve flavor after reducing fat content.", prompt: "Which choice best explains the pattern described in the text?", options: [{ id: "A", text: "Low-fat products always have less sugar" }, { id: "B", text: "Manufacturers often add sugar to compensate for flavor lost when fat is reduced" }, { id: "C", text: "Sugar content is unrelated to fat content" }, { id: "D", text: "Low-fat products are never flavored" }], answer: "B", explanation: "The text explains added sugar is used to preserve flavor after fat reduction — option B directly restates this." },
  { id: "II12", passage: "Historians long credited a single inventor with developing the modern printing press, but recent archival research has uncovered evidence of similar, independent innovations occurring in several regions around the same period.", prompt: "Which choice best describes the shift in historical understanding presented in the text?", options: [{ id: "A", text: "From crediting one inventor to recognizing multiple independent innovations" }, { id: "B", text: "From doubting any invention occurred to confirming a single inventor" }, { id: "C", text: "No shift in understanding occurred" }, { id: "D", text: "From multiple inventors to a single confirmed inventor" }], answer: "A", explanation: "The text moves from single-inventor credit to recognition of independent, parallel innovation — option A." },
  { id: "II13", passage: "A wildlife survey found that reintroduced wolf populations reduced local deer overgrazing, which in turn allowed streamside vegetation to recover, an effect researchers describe as a trophic cascade.", prompt: "Based on the text, what is the correct sequence of effects described?", options: [{ id: "A", text: "Vegetation recovery caused wolves to be reintroduced" }, { id: "B", text: "Wolves reduced deer grazing, which allowed vegetation to recover" }, { id: "C", text: "Deer grazing increased after wolves were reintroduced" }, { id: "D", text: "Wolves had no measurable effect on vegetation" }], answer: "B", explanation: "The passage describes a causal chain: wolves → reduced grazing → vegetation recovery — option B." },
  { id: "II14", passage: "A publisher's internal data showed that audiobook sales grew fastest among readers over 60, a demographic the marketing team had not originally targeted when the audiobook division launched.", prompt: "Which choice is most strongly supported by the text?", options: [{ id: "A", text: "The marketing team's original targeting assumptions did not match the actual audience growth" }, { id: "B", text: "Audiobooks are exclusively popular among younger readers" }, { id: "C", text: "The audiobook division was canceled" }, { id: "D", text: "Sales data showed no clear pattern" }], answer: "A", explanation: "An unexpected demographic driving growth implies the original targeting missed the mark — option A." },
  { id: "II15", passage: "Contrary to the assumption that larger animals always require proportionally more food, some large herbivores have slower metabolisms relative to their body size, allowing them to survive on comparatively less food per unit of body mass than smaller relatives.", prompt: "Which choice best states the main point of the text?", options: [{ id: "A", text: "Larger animals always need more food per unit of body mass" }, { id: "B", text: "Body size alone does not determine an animal's food needs relative to its mass" }, { id: "C", text: "Smaller animals never need food" }, { id: "D", text: "Metabolism has no relationship to body size" }], answer: "B", explanation: "The text challenges a size-based assumption by pointing to metabolism as a separate factor — option B." },
  { id: "II16", passage: "A regional water authority reported that leak repairs completed this year saved an estimated 40 million gallons, though the authority also acknowledged that aging infrastructure elsewhere in the system likely offset some of those gains through new leaks.", prompt: "Which choice best reflects the overall picture presented in the text?", options: [{ id: "A", text: "The repairs guaranteed a net gain with no complications" }, { id: "B", text: "Gains from repairs may be partially offset by ongoing infrastructure problems" }, { id: "C", text: "No water was saved this year" }, { id: "D", text: "All infrastructure in the system has been replaced" }], answer: "B", explanation: "The text pairs a reported gain with an acknowledged offsetting factor — option B." },
  { id: "II17", passage: "An analysis of hiring records at a mid-sized firm found that candidates who completed a skills-based assessment were hired at similar rates regardless of which university they attended, a pattern that contrasted with hiring data from before the assessment was introduced.", prompt: "Which choice best describes the change indicated by the text?", options: [{ id: "A", text: "University attended became a stronger predictor of hiring after the assessment" }, { id: "B", text: "The introduction of the assessment coincided with reduced influence of university attended on hiring outcomes" }, { id: "C", text: "The firm stopped hiring entirely" }, { id: "D", text: "No hiring data was collected before the assessment" }], answer: "B", explanation: "The passage contrasts pre- and post-assessment patterns, showing reduced influence of university — option B." },
  { id: "II18", passage: "A geologist's core samples from a lakebed revealed alternating layers of coarse and fine sediment, a pattern typically associated with seasonal changes in water flow rather than a single catastrophic event.", prompt: "According to the text, what do the alternating sediment layers most likely indicate?", options: [{ id: "A", text: "A single sudden flood" }, { id: "B", text: "Regular, seasonal variation in water flow over time" }, { id: "C", text: "The complete absence of water flow" }, { id: "D", text: "Volcanic activity" }], answer: "B", explanation: "The text explicitly attributes the layering to seasonal flow variation, not a single event — option B." },
  { id: "II19", passage: "A field experiment comparing two irrigation methods found that drip irrigation used 30 percent less water than sprinkler irrigation while producing statistically similar crop yields, though drip systems required a higher upfront installation cost.", prompt: "Which choice best summarizes the trade-off described in the text?", options: [{ id: "A", text: "Drip irrigation is worse in every measured category" }, { id: "B", text: "Drip irrigation saves water and matches yields, but costs more to install initially" }, { id: "C", text: "Sprinkler irrigation uses less water than drip irrigation" }, { id: "D", text: "Crop yields were significantly lower under drip irrigation" }], answer: "B", explanation: "The text presents water savings and equal yield as benefits, balanced against higher installation cost — option B." },
  { id: "II20", passage: "A museum curator noted that visitor surveys showed strong interest in interactive exhibits, yet attendance data showed visitors spent, on average, less time at interactive stations than at traditional display cases.", prompt: "Which choice best describes the apparent contradiction in the text?", options: [{ id: "A", text: "Stated interest in interactive exhibits did not match the observed time visitors actually spent at them" }, { id: "B", text: "Visitors reported no interest in interactive exhibits" }, { id: "C", text: "Traditional displays were removed from the museum" }, { id: "D", text: "Attendance data confirmed the survey results exactly" }], answer: "A", explanation: "The text sets up a gap between stated preference (surveys) and observed behavior (time spent) — option A." }
  ],
  "standard-english-conventions": [
  { id: "SC01", passage: "The committee reviewed three proposals, each one addressing a different aspect of the ______ budget shortfall.", prompt: "Which choice completes the text so that it conforms to the conventions of Standard English?", options: [{ id: "A", text: "citys" }, { id: "B", text: "city's" }, { id: "C", text: "citie's" }, { id: "D", text: "cities" }], answer: "B", explanation: "A singular possessive noun (belonging to one city) requires an apostrophe-s: city's." },
  { id: "SC02", passage: "Marcus, who had trained for the marathon all spring, still felt nervous ______ he crossed the starting line.", prompt: "Which choice completes the text so that it conforms to the conventions of Standard English?", options: [{ id: "A", text: "as" }, { id: "B", text: "as," }, { id: "C", text: "as;" }, { id: "D", text: "as:" }], answer: "A", explanation: "No punctuation is needed before the subordinate clause 'as he crossed the starting line' when it follows the main clause directly." },
  { id: "SC03", passage: "The research team published their findings, the data had been collected over three years.", prompt: "Which choice completes the text so that it conforms to the conventions of Standard English?", options: [{ id: "A", text: "findings, the data" }, { id: "B", text: "findings; the data" }, { id: "C", text: "findings the data" }, { id: "D", text: "findings: and the data" }], answer: "B", explanation: "Two independent clauses need a semicolon (or period) between them rather than a comma, which creates a comma splice." },
  { id: "SC04", passage: "Neither the manager nor the employees ______ aware of the policy change until the memo arrived.", prompt: "Which choice completes the text so that it conforms to the conventions of Standard English?", options: [{ id: "A", text: "was" }, { id: "B", text: "were" }, { id: "C", text: "is" }, { id: "D", text: "has been" }], answer: "B", explanation: "With 'neither...nor,' the verb agrees with the nearer subject, 'employees' (plural), so 'were' is correct." },
  { id: "SC05", passage: "Having finished the experiment, the results were recorded by the students.", prompt: "Which choice best revises the sentence to correct the dangling modifier?", options: [{ id: "A", text: "Having finished the experiment, the results were recorded by the students." }, { id: "B", text: "Having finished the experiment, the students recorded the results." }, { id: "C", text: "The results, having finished the experiment, were recorded by the students." }, { id: "D", text: "The experiment having finished, results were recorded." }], answer: "B", explanation: "The introductory phrase 'Having finished the experiment' must modify the doer of the action — the students — so the subject following the comma should be 'the students.'" },
  { id: "SC06", passage: "Each of the applicants ______ required to submit three letters of recommendation.", prompt: "Which choice completes the text so that it conforms to the conventions of Standard English?", options: [{ id: "A", text: "are" }, { id: "B", text: "is" }, { id: "C", text: "were" }, { id: "D", text: "have been" }], answer: "B", explanation: "'Each' is singular, so it takes the singular verb 'is,' regardless of the plural noun in the prepositional phrase that follows." },
  { id: "SC07", passage: "The novel, praised for it's vivid imagery, sold poorly upon release.", prompt: "Which choice completes the text so that it conforms to the conventions of Standard English?", options: [{ id: "A", text: "it's" }, { id: "B", text: "its" }, { id: "C", text: "its'" }, { id: "D", text: "their" }], answer: "B", explanation: "The possessive form of 'it' has no apostrophe: 'its.' 'It's' is a contraction of 'it is.'" },
  { id: "SC08", passage: "The professor assigned readings on three topics: ecology, ______ and urban planning.", prompt: "Which choice completes the text so that it conforms to the conventions of Standard English?", options: [{ id: "A", text: "economics" }, { id: "B", text: "economics," }, { id: "C", text: "economics;" }, { id: "D", text: "economics -" }], answer: "B", explanation: "In a list of three items, a comma is needed before the final item and the conjunction ('economics, and urban planning')." },
  { id: "SC09", passage: "The team's strategy, which had worked well in previous seasons, failing to produce results this year.", prompt: "Which choice completes the text so that it conforms to the conventions of Standard English?", options: [{ id: "A", text: "failing" }, { id: "B", text: "failed" }, { id: "C", text: "fails" }, { id: "D", text: "having failed" }], answer: "B", explanation: "The sentence needs a finite main verb for its subject 'strategy'; 'failing' alone is not a complete verb, so 'failed' is correct." },
  { id: "SC10", passage: "Between you and ______, I think the proposal needs more revision before the deadline.", prompt: "Which choice completes the text so that it conforms to the conventions of Standard English?", options: [{ id: "A", text: "I" }, { id: "B", text: "me" }, { id: "C", text: "myself" }, { id: "D", text: "mine" }], answer: "B", explanation: "As the object of the preposition 'between,' the objective case pronoun 'me' is required." },
  { id: "SC11", passage: "The museum's new wing, which opened last month, feature interactive exhibits designed for children.", prompt: "Which choice completes the text so that it conforms to the conventions of Standard English?", options: [{ id: "A", text: "feature" }, { id: "B", text: "features" }, { id: "C", text: "featuring" }, { id: "D", text: "featured, " }], answer: "B", explanation: "The subject 'wing' is singular, so the verb must be 'features,' not the plural 'feature.'" },
  { id: "SC12", passage: "Whichever candidate wins the primary will face significant challenges; ______ campaign has struggled with fundraising all year.", prompt: "Which choice completes the text so that it conforms to the conventions of Standard English?", options: [{ id: "A", text: "their" }, { id: "B", text: "his or her" }, { id: "C", text: "there" }, { id: "D", text: "they're" }], answer: "B", explanation: "'Whichever candidate' is a singular antecedent, so the singular possessive 'his or her' is grammatically correct in this formal context." },
  { id: "SC13", passage: "The report outlines several key findings: increased revenue, ______ decreased operating costs, and higher customer satisfaction.", prompt: "Which choice completes the text so that it conforms to the conventions of Standard English?", options: [{ id: "A", text: "reduced staff turnover," }, { id: "B", text: "reduced staff turnover" }, { id: "C", text: "reduced staff turnover;" }, { id: "D", text: "reduced staff turnover:" }], answer: "A", explanation: "Items in a list are separated consistently by commas; a comma after 'turnover' matches the punctuation pattern of the rest of the list." },
  { id: "SC14", passage: "The bridge, built in 1932 and renovated twice since, remain one of the city's most photographed landmarks.", prompt: "Which choice completes the text so that it conforms to the conventions of Standard English?", options: [{ id: "A", text: "remain" }, { id: "B", text: "remains" }, { id: "C", text: "remaining" }, { id: "D", text: "have remained" }], answer: "B", explanation: "The subject 'bridge' is singular, so despite the intervening clause, the verb must be 'remains.'" },
  { id: "SC15", passage: "The scientists gathered data from over a dozen sites, they later combined the results into a single report.", prompt: "Which choice completes the text so that it conforms to the conventions of Standard English?", options: [{ id: "A", text: "sites, they" }, { id: "B", text: "sites. They" }, { id: "C", text: "sites, and they" }, { id: "D", text: "Both B and C" }], answer: "D", explanation: "Both separating the independent clauses with a period ('sites. They') and joining them with a comma plus coordinating conjunction ('sites, and they') correctly fix the comma splice." },
  { id: "SC16", passage: "Running through the checklist twice, no errors were found by the technician before the launch.", prompt: "Which choice best revises the sentence to correct the dangling modifier?", options: [{ id: "A", text: "Running through the checklist twice, no errors were found by the technician before the launch." }, { id: "B", text: "Running through the checklist twice, the technician found no errors before the launch." }, { id: "C", text: "No errors, running through the checklist twice, were found before the launch." }, { id: "D", text: "Before the launch running through the checklist twice no errors." }], answer: "B", explanation: "The introductory phrase describes the technician's action, so 'the technician' must immediately follow the comma as the subject." },
  { id: "SC17", passage: "Of the two proposals submitted, the second one is clearly the ______.", prompt: "Which choice completes the text so that it conforms to the conventions of Standard English?", options: [{ id: "A", text: "best" }, { id: "B", text: "better" }, { id: "C", text: "most best" }, { id: "D", text: "goodest" }], answer: "B", explanation: "When comparing exactly two things, the comparative form 'better' is required rather than the superlative 'best.'" },
  { id: "SC18", passage: "The company's quarterly earnings, along with its updated growth projections, ______ released to investors this morning.", prompt: "Which choice completes the text so that it conforms to the conventions of Standard English?", options: [{ id: "A", text: "was" }, { id: "B", text: "were" }, { id: "C", text: "is" }, { id: "D", text: "has been" }], answer: "B", explanation: "The subject 'earnings' is plural; the intervening phrase 'along with its updated growth projections' does not change subject-verb agreement, so 'were' is correct." },
  { id: "SC19", passage: "The instructor asked each student to submit their essay by Friday, a deadline that gave everyone plenty of time to revise.", prompt: "Which choice completes the text so that it conforms to the conventions of Standard English in a formal register?", options: [{ id: "A", text: "their essay" }, { id: "B", text: "his or her essay" }, { id: "C", text: "essay's" }, { id: "D", text: "the essays'" }], answer: "B", explanation: "'Each student' is singular, so formal Standard English calls for the singular possessive 'his or her,' matching the singular antecedent." },
  { id: "SC20", passage: "The garden, once overgrown with weeds, now bloom with roses, tulips, and daffodils every spring.", prompt: "Which choice completes the text so that it conforms to the conventions of Standard English?", options: [{ id: "A", text: "bloom" }, { id: "B", text: "blooms" }, { id: "C", text: "blooming" }, { id: "D", text: "have bloomed" }], answer: "B", explanation: "The singular subject 'garden' requires the singular verb 'blooms.'" }
  ],
  "expression-of-ideas": [
  { id: "EI01", passage: "The city's new bike-share program launched last spring. ______, ridership numbers have already exceeded the first-year projections by 40 percent.", prompt: "Which choice completes the text with the most logical transition?", options: [{ id: "A", text: "However" }, { id: "B", text: "In fact" }, { id: "C", text: "Nevertheless" }, { id: "D", text: "On the other hand" }], answer: "B", explanation: "The second sentence reinforces and intensifies the first (exceeding projections), which calls for 'In fact,' not a contrast word." },
  { id: "EI02", passage: "The lab's new equipment cut processing time by half. ______, the equipment's high cost has strained the department's annual budget.", prompt: "Which choice completes the text with the most logical transition?", options: [{ id: "A", text: "Similarly" }, { id: "B", text: "However" }, { id: "C", text: "For example" }, { id: "D", text: "In addition" }], answer: "B", explanation: "The second sentence introduces a drawback that contrasts with the benefit described first, so 'However' fits." },
  { id: "EI03", passage: "A student is writing a report on renewable energy and has gathered these notes: (1) Solar panel costs have dropped 70% since 2010. (2) Wind turbine efficiency has roughly doubled in the same period. (3) Battery storage remains the primary bottleneck for grid-scale renewable adoption.\nThe student wants to emphasize the main obstacle currently limiting renewable energy expansion. Which choice most effectively uses relevant information from the notes to accomplish this goal?", prompt: "Which choice best accomplishes the stated goal?", options: [{ id: "A", text: "Solar panel costs have dropped 70% since 2010, making renewables cheaper than ever." }, { id: "B", text: "Despite falling costs and rising efficiency, battery storage remains the primary bottleneck limiting grid-scale renewable adoption." }, { id: "C", text: "Wind turbine efficiency has roughly doubled since 2010." }, { id: "D", text: "Solar and wind technology have both improved significantly in the past decade." }], answer: "B", explanation: "Only option B directly states the 'main obstacle' (storage) while using the cost/efficiency notes as context, matching the stated goal." },
  { id: "EI04", passage: "The orchestra's rehearsal ran long because of a scheduling conflict. ______, the musicians managed to prepare fully for opening night.", prompt: "Which choice completes the text with the most logical transition?", options: [{ id: "A", text: "Consequently" }, { id: "B", text: "Nonetheless" }, { id: "C", text: "Therefore" }, { id: "D", text: "As a result" }], answer: "B", explanation: "Despite the setback (rehearsal running long), the musicians still succeeded — a contrast word like 'Nonetheless' is needed, not a cause-effect word." },
  { id: "EI05", passage: "A writer wants to add a sentence that provides a specific example supporting the claim that urban gardening has grown rapidly. Which choice best accomplishes this goal?", prompt: "Which choice best accomplishes the stated goal?", options: [{ id: "A", text: "Many people enjoy gardening as a hobby." }, { id: "B", text: "In Detroit alone, the number of registered community garden plots rose from 80 to over 1,400 between 2000 and 2020." }, { id: "C", text: "Gardening can improve mental health." }, { id: "D", text: "Urban areas face many environmental challenges." }], answer: "B", explanation: "Only option B provides a specific, quantified example (a real number and location) that directly supports rapid growth in urban gardening." },
  { id: "EI06", passage: "The bakery's original recipe called for imported flour. ______, the owner switched to a locally sourced alternative after supply chain delays became frequent.", prompt: "Which choice completes the text with the most logical transition?", options: [{ id: "A", text: "Eventually" }, { id: "B", text: "Similarly" }, { id: "C", text: "For instance" }, { id: "D", text: "In other words" }], answer: "A", explanation: "The sentence describes a change happening after a period of time (recurring delays), so a time-based transition, 'Eventually,' fits best." },
  { id: "EI07", passage: "A student has written these notes for a paragraph: (1) The library's late-night study hours were introduced in 2019. (2) Usage data shows a 25% increase in overall visits since the change. (3) Survey respondents cited the extended hours as their top reason for visiting more often.\nThe student wants to conclude the paragraph by explaining why visits increased. Which choice most effectively uses the notes to accomplish this goal?", prompt: "Which choice best accomplishes the stated goal?", options: [{ id: "A", text: "The library was built in 1985." }, { id: "B", text: "Survey respondents most often credited the extended hours for their increased visits, directly linking the 2019 change to the usage increase." }, { id: "C", text: "The library added new study hours in 2019." }, { id: "D", text: "Visits to the library have changed over time." }], answer: "B", explanation: "Only option B connects the survey data (note 3) to the reason for the increase, fulfilling the 'explain why' goal." },
  { id: "EI08", passage: "The proposed highway expansion promised shorter commute times. ______, residents along the route voiced strong opposition due to noise and property concerns.", prompt: "Which choice completes the text with the most logical transition?", options: [{ id: "A", text: "Likewise" }, { id: "B", text: "Yet" }, { id: "C", text: "Thus" }, { id: "D", text: "Specifically" }], answer: "B", explanation: "A promised benefit is being contrasted with opposition — 'Yet' signals this contrast correctly." },
  { id: "EI09", passage: "A writer wants to add a sentence that acknowledges a limitation of the study being discussed. Which choice best accomplishes this goal?", prompt: "Which choice best accomplishes the stated goal?", options: [{ id: "A", text: "The study's authors are respected researchers in the field." }, { id: "B", text: "The study's sample size, however, was limited to a single region, so its findings may not generalize nationally." }, { id: "C", text: "The study was published in a peer-reviewed journal." }, { id: "D", text: "The study took three years to complete." }], answer: "B", explanation: "Only option B identifies a specific limitation (small, regional sample) and its consequence (limited generalizability)." },
  { id: "EI10", passage: "The startup's first product failed to gain traction. ______, its second product, launched a year later, became an industry standard.", prompt: "Which choice completes the text with the most logical transition?", options: [{ id: "A", text: "In contrast" }, { id: "B", text: "Similarly" }, { id: "C", text: "As a result" }, { id: "D", text: "For example" }], answer: "A", explanation: "The sentence contrasts a failure with a later success — 'In contrast' is the correct transition." },
  { id: "EI11", passage: "A student is drafting a paragraph and has these notes: (1) The town's recycling program began in 2015. (2) Participation was low in the first two years. (3) A 2018 rule requiring color-coded bins caused participation to triple within one year.\nThe student wants to identify the specific change that most improved participation. Which choice best accomplishes this goal?", prompt: "Which choice best accomplishes the stated goal?", options: [{ id: "A", text: "The recycling program began in 2015." }, { id: "B", text: "Participation was low during the program's first two years." }, { id: "C", text: "The introduction of color-coded bins in 2018 tripled participation within a year." }, { id: "D", text: "Recycling programs benefit the environment." }], answer: "C", explanation: "Only option C names the specific change (color-coded bins) and its measured effect (tripled participation), matching the goal exactly." },
  { id: "EI12", passage: "The new policy was intended to reduce paperwork for small businesses. ______, many owners reported that compliance actually required more documentation than before.", prompt: "Which choice completes the text with the most logical transition?", options: [{ id: "A", text: "Indeed" }, { id: "B", text: "Instead" }, { id: "C", text: "Similarly" }, { id: "D", text: "Therefore" }], answer: "B", explanation: "The outcome (more paperwork) is the opposite of the stated intention, so 'Instead' fits." },
  { id: "EI13", passage: "A writer wants to add a sentence introducing a counterargument before addressing it later in the essay. Which choice best accomplishes this goal?", prompt: "Which choice best accomplishes the stated goal?", options: [{ id: "A", text: "Critics argue that the new zoning laws will drive up housing costs in already expensive neighborhoods." }, { id: "B", text: "Zoning laws determine how land can be used in a city." }, { id: "C", text: "The city council voted on the zoning laws last month." }, { id: "D", text: "Housing costs have risen in many cities recently." }], answer: "A", explanation: "Only option A presents an opposing viewpoint ('Critics argue') framed as a counterargument to be addressed." },
  { id: "EI14", passage: "The film received lukewarm reviews upon its initial release. ______, it has since developed a devoted cult following.", prompt: "Which choice completes the text with the most logical transition?", options: [{ id: "A", text: "Consequently" }, { id: "B", text: "Since then" }, { id: "C", text: "In spite of this" }, { id: "D", text: "Similarly" }], answer: "C", explanation: "Developing a devoted following despite lukewarm reviews is a contrast, best signaled by 'In spite of this.'" },
  { id: "EI15", passage: "A student wants to add a sentence that provides background context before discussing a specific policy change. Which choice best accomplishes this goal?", prompt: "Which choice best accomplishes the stated goal?", options: [{ id: "A", text: "The city council recently voted to change parking regulations downtown." }, { id: "B", text: "Downtown parking has been a contentious issue in the city for over a decade, with complaints steadily increasing each year." }, { id: "C", text: "Parking meters accept both coins and cards." }, { id: "D", text: "The mayor was elected three years ago." }], answer: "B", explanation: "Option B establishes broader background (a long-running issue) rather than jumping straight to the specific change, matching the 'background context' goal." },
  { id: "EI16", passage: "Sales of the product dipped sharply in its second quarter. ______, the marketing team had already begun planning a redesign before the dip occurred.", prompt: "Which choice completes the text with the most logical transition?", options: [{ id: "A", text: "Notably" }, { id: "B", text: "As a result" }, { id: "C", text: "Therefore" }, { id: "D", text: "Consequently" }], answer: "A", explanation: "The sentence adds a noteworthy, somewhat unexpected fact (planning began before the dip) rather than stating a result of the dip, so 'Notably' fits best." },
  { id: "EI17", passage: "A writer wants to combine two short sentences — 'The bridge was completed in 1937. It remains the longest suspension bridge in the region.' — into one sentence using a subordinating conjunction. Which choice best accomplishes this goal?", prompt: "Which choice best accomplishes the stated goal?", options: [{ id: "A", text: "The bridge was completed in 1937, and it remains the longest suspension bridge in the region." }, { id: "B", text: "Although the bridge was completed in 1937, it remains the longest suspension bridge in the region." }, { id: "C", text: "The bridge was completed in 1937. It remains the longest suspension bridge in the region." }, { id: "D", text: "The bridge, completed in 1937, remains the longest suspension bridge in the region; however." }], answer: "B", explanation: "Only option B uses a subordinating conjunction ('Although') to combine the two ideas into a single sentence, as the goal specifies." },
  { id: "EI18", passage: "The vaccine trial showed strong results in adults. ______, researchers have not yet tested its effectiveness in children under twelve.", prompt: "Which choice completes the text with the most logical transition?", options: [{ id: "A", text: "Similarly" }, { id: "B", text: "However" }, { id: "C", text: "Thus" }, { id: "D", text: "For example" }], answer: "B", explanation: "A limitation (untested age group) is being contrasted with the earlier positive result, so 'However' is correct." },
  { id: "EI19", passage: "A student wants to add a concluding sentence that restates the paragraph's main claim about renewable energy investment using different wording. Which choice best accomplishes this goal?", prompt: "Which choice best accomplishes the stated goal?", options: [{ id: "A", text: "In short, directing more capital toward renewable infrastructure remains essential to the region's long-term energy goals." }, { id: "B", text: "Solar panels are becoming more efficient every year." }, { id: "C", text: "The region currently relies mostly on natural gas." }, { id: "D", text: "Renewable energy investment increased last year." }], answer: "A", explanation: "Only option A functions as a restated conclusion ('In short...') summarizing the broader claim, rather than introducing a new fact." },
  { id: "EI20", passage: "The committee debated the proposal for nearly three hours. ______, they reached no final decision and scheduled a follow-up meeting.", prompt: "Which choice completes the text with the most logical transition?", options: [{ id: "A", text: "Ultimately" }, { id: "B", text: "For example" }, { id: "C", text: "Similarly" }, { id: "D", text: "In addition" }], answer: "A", explanation: "The sentence describes the final outcome of the long debate, which calls for 'Ultimately.'" }
  ],
};
